    /**
     * Method to retrieve the Customer via an CustomerPrimaryKey.
     * @param 	id Long
     * @return 	Customer
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Customer handle( FindCustomerQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCustomerId() );
    }
    
    /**
     * Method to retrieve a collection of all Customers
     *
     * @param	query	FindAllCustomerQuery 
     * @return 	List<Customer> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Customer> handle( FindAllCustomerQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCustomer,
 * but only if the id matches
 *
 * @param		entity	Customer
 */
	protected void emitFindCustomer( Customer entity ) {
		LOGGER.info("handling emitFindCustomer" );
		
	    queryUpdateEmitter.emit(FindCustomerQuery.class,
	                            query -> query.getFilter().getCustomerId().equals(entity.getCustomerId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCustomer
	 * 
	 * @param		entity	Customer
	 */
	protected void emitFindAllCustomer( Customer entity ) {
		LOGGER.info("handling emitFindAllCustomer" );
		
	    queryUpdateEmitter.emit(FindAllCustomerQuery.class,
	                            query -> true,
	                            entity);
	}

